// Renders the dashboard as one self-contained HTML page: inline CSS, no scripts.
// Every value is HTML-escaped, because test names and failure messages come from CI reports.
const data = $input.first().json;
const FLAKY_FLIPS = 3; // same rule as the quality gate

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
// Test IDs are long; let them wrap after '::' and '.' instead of mid-word.
const testName = (id) => esc(id).replace(/\./g, '.<wbr>').replace(/::/g, '::<wbr>');
const pct = (value) => (value === null || value === undefined ? '–' : `${Number(value).toFixed(1)}%`);
const secs = (ms) => `${(Number(ms) / 1000).toFixed(1)} s`;
const when = (iso) => DateTime.fromISO(iso).toFormat('d LLL yyyy, HH:mm');
const level = (rate) => (rate === null ? 'none' : rate >= 95 ? 'good' : rate >= 80 ? 'warn' : 'bad');
const link = (project, branch) => `?project=${encodeURIComponent(project)}&branch=${encodeURIComponent(branch)}`;
const table = (headers, rows, empty) => rows.length === 0 ? `<p class="empty">${empty}</p>` :
  `<table><thead><tr>${headers.map((h) => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`;

let title;
let body;
if (!data.project) {
  title = 'QA dashboard';
  body = `<p class="sub">Every project and branch that has sent test results.</p>
  <section class="card">${table(['Project', 'Branch', 'Runs', 'Last pass rate', 'Last failures', 'Last run'],
    data.projects.map((p) => `<tr><td><a href="${esc(link(p.project, p.branch))}">${esc(p.project)}</a></td>
      <td>${esc(p.branch)}</td><td class="num">${p.runs}</td>
      <td class="num"><span class="pill ${level(p.last_pass_rate)}">${pct(p.last_pass_rate)}</span></td>
      <td class="num">${p.last_failed}</td><td>${esc(when(p.last_run_at))}</td></tr>`),
    'No test results yet. Send a JUnit report to <code>POST /webhook/qa/results</code>.')}</section>`;
} else if (data.runs.length === 0) {
  title = `QA dashboard: ${data.project}`;
  body = `<p class="sub">No runs recorded for <strong>${esc(data.project)}</strong> on branch
    <strong>${esc(data.branch)}</strong> yet. <a href="?">All projects</a></p>`;
} else {
  title = `QA dashboard: ${data.project}`;
  const latest = data.runs[0];
  const flakyCount = data.unstable.filter((t) => t.flips >= FLAKY_FLIPS || t.passed_on_retry > 0).length;
  const bars = [...data.runs].reverse().map((r) =>
    `<div class="bar ${level(r.pass_rate)}" style="height:${Math.max(Number(r.pass_rate ?? 0), 2)}%"
      title="Run ${r.id}: ${pct(r.pass_rate)} (${r.failed} failed)"></div>`).join('');
  body = `<p class="sub"><a href="?">All projects</a> · branch <strong>${esc(data.branch)}</strong></p>
  <div class="cards">
    <div class="card stat"><span>Last pass rate</span><strong class="${level(latest.pass_rate)}">${pct(latest.pass_rate)}</strong></div>
    <div class="card stat"><span>Failing now</span><strong>${data.failing.length}</strong></div>
    <div class="card stat"><span>Flaky tests</span><strong>${flakyCount}</strong></div>
    <div class="card stat"><span>Runs shown</span><strong>${data.runs.length}</strong></div>
  </div>
  <section class="card"><h2>Pass rate, oldest to newest</h2><div class="trend">${bars}</div></section>
  <div class="grid">
    <section class="card"><h2>Failing in the latest run</h2>${table(['Test', 'Message'],
      data.failing.map((t) => `<tr><td><code>${testName(t.test_id)}</code></td><td class="msg">${esc((t.message ?? '').split('\n')[0])}</td></tr>`),
      'Nothing is failing.')}</section>
    <section class="card"><h2>Unstable tests, last 10 runs</h2>${table(['Test', 'Flips', 'Failures', 'Retried'],
      data.unstable.map((t) => `<tr><td><code>${testName(t.test_id)}</code>${t.flips >= FLAKY_FLIPS || t.passed_on_retry > 0 ? ' <span class="pill bad">flaky</span>' : ''}</td>
        <td class="num">${t.flips}</td><td class="num">${t.failures}/${t.runs}</td><td class="num">${t.passed_on_retry}</td></tr>`),
      'No test has changed status recently.')}</section>
  </div>
  <section class="card"><h2>Slowest tests in the latest run</h2>${table(['Test', 'Duration'],
    data.slowest.map((t) => `<tr><td><code>${testName(t.test_id)}</code></td><td class="num">${secs(t.duration_ms)}</td></tr>`), 'No timings.')}</section>
  <section class="card"><h2>Recent runs</h2>${table(['Run', 'When', 'Commit', 'Pass rate', 'Passed', 'Failed', 'Skipped', 'Duration'],
    data.runs.map((r) => `<tr><td class="num">${r.build_url ? `<a href="${esc(r.build_url)}">#${r.id}</a>` : `#${r.id}`}</td>
      <td>${esc(when(r.created_at))}</td><td><code>${esc((r.commit_sha ?? '').slice(0, 8))}</code></td>
      <td class="num"><span class="pill ${level(r.pass_rate)}">${pct(r.pass_rate)}</span></td>
      <td class="num">${r.passed}</td><td class="num">${r.failed}</td><td class="num">${r.skipped}</td>
      <td class="num">${secs(r.duration_ms)}</td></tr>`), '')}</section>`;
}

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  :root { --bg:#f6f7f9; --card:#fff; --text:#1d2330; --muted:#5d6678; --line:#e3e6ec;
          --good:#1a7f37; --warn:#9a6700; --bad:#cf222e; --good-bg:#dafbe1; --warn-bg:#fff8c5; --bad-bg:#ffebe9; }
  @media (prefers-color-scheme: dark) {
    :root { --bg:#0f1218; --card:#171b23; --text:#e6e9ef; --muted:#9aa3b2; --line:#2a303b;
            --good:#3fb950; --warn:#d29922; --bad:#f85149; --good-bg:#12261a; --warn-bg:#2a2210; --bad-bg:#2d1415; }
  }
  * { box-sizing: border-box; }
  body { margin:0; background:var(--bg); color:var(--text); font:15px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
  main { max-width:1100px; margin:0 auto; padding:24px 16px 48px; }
  h1 { margin:0 0 4px; font-size:24px; } h2 { margin:0 0 12px; font-size:16px; }
  a { color:inherit; } .sub { color:var(--muted); margin:0 0 20px; }
  .card { background:var(--card); border:1px solid var(--line); border-radius:10px; padding:16px; margin-bottom:16px; overflow-x:auto; }
  .cards { display:grid; grid-template-columns:repeat(auto-fit, minmax(170px, 1fr)); gap:16px; }
  .stat span { display:block; color:var(--muted); font-size:13px; } .stat strong { font-size:28px; }
  .grid { display:grid; grid-template-columns:repeat(auto-fit, minmax(320px, 1fr)); gap:16px; }
  .grid .card { margin-bottom:0; } .grid { margin-bottom:16px; }
  table { width:100%; border-collapse:collapse; font-size:14px; }
  th, td { text-align:left; padding:6px 8px; border-bottom:1px solid var(--line); vertical-align:top; }
  th { color:var(--muted); font-weight:600; } .num { text-align:right; white-space:nowrap; }
  code { font-size:13px; overflow-wrap:anywhere; } .msg { color:var(--muted); }
  .pill { display:inline-block; padding:1px 8px; border-radius:999px; font-size:12px; font-weight:600; }
  .pill.good { background:var(--good-bg); color:var(--good); } .pill.warn { background:var(--warn-bg); color:var(--warn); }
  .pill.bad { background:var(--bad-bg); color:var(--bad); } .pill.none { color:var(--muted); }
  strong.good { color:var(--good); } strong.warn { color:var(--warn); } strong.bad { color:var(--bad); }
  .trend { display:flex; align-items:flex-end; gap:4px; height:140px; border-bottom:1px solid var(--line); }
  .bar { flex:1; min-width:6px; border-radius:3px 3px 0 0; }
  .bar.good { background:var(--good); } .bar.warn { background:var(--warn); } .bar.bad { background:var(--bad); } .bar.none { background:var(--line); }
  .empty { color:var(--muted); margin:0; }
</style></head>
<body><main><h1>${esc(title)}</h1>${body}</main></body></html>`;

return [{ json: { html } }];
